{"command":"python3 - << 'PY'
import re
path="/app/text.gcode"
# parse M486 lines with line numbers and current Z
cur_z=None
blocks=[] # (line, type, z)
with open(path) as f:
    lines=f.readlines()
for i,line in enumerate(lines, start=1):
    if re.search(r'G[01].*Z([\d\.]+).*F720', line):
        try:
            cur_z=float(re.search(r'Z([\d\.]+)', line).group(1))
        except: pass
    if 'M486' in line:
        blocks.append((i, line.strip(), cur_z))
for b in blocks:
    print(b)
print(f"total {len(blocks)}")
PY","description":"List M486 blocks with Z"}

